def step(self, z):
    self.cruise.step(z)
    self.maneuver.step(z)
    div = float(np.linalg.norm(self.cruise.x[:2] - self.maneuver.x[:2]))
    if not self.in_maneuver and div > self.divergence_enter:
        self.in_maneuver = True
        self.switch_times.append(True)
    elif self.in_maneuver and div < self.divergence_exit:
        self.in_maneuver = False
        self.switch_times.append(False)
    return self.maneuver.x if self.in_maneuver else self.cruise.x, (
        self.maneuver.P if self.in_maneuver else self.cruise.P)

def initialize(self, z0):
    self.x = np.array([z0[0], z0[1], 0.0, 0.0])
    self.P = self.P0.copy()
